// Two illustrative worlds, not separate weather data feeds.
let aspect = frame.info.x / frame.info.y;
let tall = aspect < 1.0;
let mid = select(vec2<f32>(0.705, 0.246), vec2<f32>(0.50, 0.409), tall);
let separation = select(0.105, 0.19, tall) * aspect;
let radius = select(0.105, 0.084, tall);
let pixel = 1.0 / frame.info.y;
let aa = pixel / radius;
let q = (uv - mid) * vec2<f32>(aspect, 1.0);
let t = frame.info.z;
let cell = floor(position.xy / 4.0);
let seed = fract(sin(dot(cell, vec2<f32>(17.127, 81.217))) * 43758.54);
let spot = fract(position.xy / 4.0) - 0.5;
let stars = smoothstep(0.994, 1.0, seed) * exp(-16.0 * dot(spot, spot));
let bridge = (1.0 - smoothstep(pixel, 2.0 * pixel, abs(q.y))) * (1.0 - smoothstep(separation - pixel, separation + pixel, abs(q.x)));
let sky = vec3<f32>(0.014, 0.028, 0.052) + vec3<f32>(0.020, 0.052, 0.067) * exp(-4.5 * length(q)) + stars * vec3<f32>(0.42, 0.52, 0.60) + bridge * vec3<f32>(0.13, 0.20, 0.23);
let light = normalize(vec3<f32>(-0.58, 0.42, 0.62));
let teal = vec3<f32>(0.20, 0.87, 0.78);
let amber = vec3<f32>(1.0, 0.64, 0.32);

let pA = (q + vec2<f32>(separation, 0.0)) / radius;
let rA = length(pA);
let zA = sqrt(max(0.00001, 1.0 - rA * rA));
let nA = normalize(vec3<f32>(pA.x, -pA.y, zA));
let latA = asin(clamp(nA.y, -1.0, 1.0));
let lonA = atan2(nA.x, nA.z) + t * 0.12;
let dayA = clamp(dot(nA, light) * 1.2 + 0.12, 0.10, 1.0);
let flowA = latA * 3.15 + 0.75 * sin(lonA * 4.0 + latA * 2.0) + 0.30 * cos(lonA * 7.0 - latA * 4.5);
let stripeA = flowA * 3.2;
let contourA = 1.0 - smoothstep(0.02, clamp(fwidth(stripeA) * 1.2, 0.045, 0.30), abs(fract(stripeA + 0.5) - 0.5));
let meridianA = 1.0 - smoothstep(0.02, 0.065, abs(fract(lonA * 2.2 + 0.5) - 0.5));
let rimA = pow(max(0.0, 1.0 - zA), 3.2);
let diskA = vec3<f32>(0.026, 0.19, 0.23) * (0.42 + dayA * (0.82 + 0.48 * sin(flowA * 2.3))) + teal * ((0.42 * contourA + 0.11 * meridianA) * dayA + rimA * (0.15 + 0.28 * dayA));
let maskA = 1.0 - smoothstep(1.0 - aa, 1.0 + aa, rA);
let glowA = 0.12 * exp(-max(0.0, rA - 1.0) * 21.0) * (1.0 - maskA) + 0.50 * exp(-abs(rA - 1.0) / max(0.75 * aa, 0.001));

let pB = (q - vec2<f32>(separation, 0.0)) / radius;
let rB = length(pB);
let zB = sqrt(max(0.00001, 1.0 - rB * rB));
let nB = normalize(vec3<f32>(pB.x, -pB.y, zB));
let latB = asin(clamp(nB.y, -1.0, 1.0));
let lonB = atan2(nB.x, nB.z) + 1.8 - t * 0.085;
let dayB = clamp(dot(nB, light) * 1.2 + 0.12, 0.10, 1.0);
let flowB = latB * 3.15 + 0.75 * sin(lonB * 4.0 + latB * 2.0) + 0.30 * cos(lonB * 7.0 - latB * 4.5);
let stripeB = flowB * 3.2;
let contourB = 1.0 - smoothstep(0.02, clamp(fwidth(stripeB) * 1.2, 0.045, 0.30), abs(fract(stripeB + 0.5) - 0.5));
let meridianB = 1.0 - smoothstep(0.02, 0.065, abs(fract(lonB * 2.2 + 0.5) - 0.5));
let rimB = pow(max(0.0, 1.0 - zB), 3.2);
let diskB = vec3<f32>(0.28, 0.12, 0.085) * (0.42 + dayB * (0.82 + 0.48 * sin(flowB * 2.3))) + amber * ((0.42 * contourB + 0.11 * meridianB) * dayB + rimB * (0.15 + 0.28 * dayB));
let maskB = 1.0 - smoothstep(1.0 - aa, 1.0 + aa, rB);
let glowB = 0.12 * exp(-max(0.0, rB - 1.0) * 21.0) * (1.0 - maskB) + 0.50 * exp(-abs(rB - 1.0) / max(0.75 * aa, 0.001));

let first = mix(sky, diskA, maskA) + teal * glowA;
return vec4<f32>(mix(first, diskB, maskB) + amber * glowB, 1.0);

